#include <WiFi.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// ===== WIFI =====
const char* ssid = "Mohamad saad";
const char* password = "Ss3100520@@##";

// ===== OLED =====
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET -1
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

// ===== MOTOR DRIVER 1 =====
#define M1_IN1 25
#define M1_IN2 26
#define M2_IN1 27
#define M2_IN2 14
#define M1_EN 13
#define M2_EN 12

// ===== MOTOR DRIVER 2 =====
#define M3_IN1 16
#define M3_IN2 17
#define M4_IN1 18
#define M4_IN2 19
#define M3_EN 23
#define M4_EN 22

void stopMotors() {
  digitalWrite(M1_IN1, LOW);
  digitalWrite(M1_IN2, LOW);
  digitalWrite(M2_IN1, LOW);
  digitalWrite(M2_IN2, LOW);
  digitalWrite(M3_IN1, LOW);
  digitalWrite(M3_IN2, LOW);
  digitalWrite(M4_IN1, LOW);
  digitalWrite(M4_IN2, LOW);
}

void setupMotors() {
  pinMode(M1_IN1, OUTPUT);
  pinMode(M1_IN2, OUTPUT);
  pinMode(M2_IN1, OUTPUT);
  pinMode(M2_IN2, OUTPUT);
  pinMode(M3_IN1, OUTPUT);
  pinMode(M3_IN2, OUTPUT);
  pinMode(M4_IN1, OUTPUT);
  pinMode(M4_IN2, OUTPUT);

  pinMode(M1_EN, OUTPUT);
  pinMode(M2_EN, OUTPUT);
  pinMode(M3_EN, OUTPUT);
  pinMode(M4_EN, OUTPUT);

  digitalWrite(M1_EN, LOW);
  digitalWrite(M2_EN, LOW);
  digitalWrite(M3_EN, LOW);
  digitalWrite(M4_EN, LOW);

  stopMotors();
}

void showFace(const char* mood) {
  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);

  display.drawRoundRect(5, 5, 118, 54, 10, SSD1306_WHITE);

  if (strcmp(mood, "happy") == 0) {
    display.drawCircle(42, 27, 5, SSD1306_WHITE);
    display.drawCircle(86, 27, 5, SSD1306_WHITE);
    display.drawLine(48, 43, 80, 43, SSD1306_WHITE);
  } else if (strcmp(mood, "sad") == 0) {
    display.drawCircle(42, 27, 5, SSD1306_WHITE);
    display.drawCircle(86, 27, 5, SSD1306_WHITE);
    display.drawLine(48, 48, 64, 42, SSD1306_WHITE);
    display.drawLine(64, 42, 80, 48, SSD1306_WHITE);
  } else if (strcmp(mood, "surprised") == 0) {
    display.drawCircle(42, 27, 6, SSD1306_WHITE);
    display.drawCircle(86, 27, 6, SSD1306_WHITE);
    display.drawCircle(64, 45, 5, SSD1306_WHITE);
  } else {
    display.fillCircle(42, 27, 5, SSD1306_WHITE);
    display.fillCircle(86, 27, 5, SSD1306_WHITE);
    display.drawLine(48, 43, 80, 43, SSD1306_WHITE);
  }

  display.display();
}

void setup() {
  Serial.begin(115200);

  setupMotors();

  Wire.begin(21, 22);

  if (display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    showFace("happy");
  }

  WiFi.mode(WIFI_STA);
  WiFi.begin(ssid, password);

  Serial.print("Connecting to WiFi");

  int attempts = 0;
  while (WiFi.status() != WL_CONNECTED && attempts < 30) {
    delay(500);
    Serial.print(".");
    attempts++;
  }

  if (WiFi.status() == WL_CONNECTED) {
    Serial.println("\nWiFi Connected!");
    Serial.println(WiFi.localIP());
  } else {
    Serial.println("\nWiFi Connection Failed!");
  }

  Serial.println("Robot is ready.");
  Serial.println("Motors are disabled for safety.");
}

void loop() {
  if (WiFi.status() != WL_CONNECTED) {
    WiFi.reconnect();
  }

  delay(1000);
}
